api_examples:
TypeScript streaming (async iterable):
for await (const chunk of client.responses.streamGeneration({ prompt: 'Hello' })) {
  if (chunk.metadata?.final_chunk) {
    handleFinal(chunk)
  }
}

Go streaming (channel):
ch := client.StreamGeneration(ctx, req)
for c := range ch {
  if c.Metadata["final_chunk"] == "1" {
    handleFinal(c)
  }
}
